const data = context.panel.data || { series: [] };
const isDark = Boolean(context.grafana.theme.isDark);

const valueAt = (field, index) => {
  if (!field || !field.values) {
    return undefined;
  }

  const values = field.values;
  if (typeof values.get === 'function') {
    return values.get(index);
  }

  if (Array.isArray(values)) {
    return values[index];
  }

  if (values.buffer) {
    return values.buffer[index];
  }

  return values[index];
};

const frameFields = (frame) => {
  const rawFields = frame.fields || (frame.schema && frame.schema.fields) || [];
  const dataValues = frame.data && frame.data.values ? frame.data.values : [];

  return rawFields.map((field, index) => ({
    ...field,
    values: field.values || dataValues[index],
  }));
};

const fieldLength = (field) => {
  if (!field || !field.values) {
    return 0;
  }

  if (Number.isFinite(field.values.length)) {
    return field.values.length;
  }

  if (field.values.buffer && Number.isFinite(field.values.buffer.length)) {
    return field.values.buffer.length;
  }

  return 0;
};

const frameRefId = (frame) => frame.refId || (frame.schema && frame.schema.refId) || '';

const frameLength = (frame) => {
  if (Number.isFinite(frame.length)) {
    return frame.length;
  }

  if (frame.data && frame.data.values && frame.data.values[0] && Number.isFinite(frame.data.values[0].length)) {
    return frame.data.values[0].length;
  }

  return Math.max(0, ...frameFields(frame).map(fieldLength));
};

const frameRows = (frame) => {
  const fields = frameFields(frame);
  const length = frameLength(frame);
  const numberField = fields.find((field) => field.type === 'number');
  const frameLabels = {
    ...(frame.labels || {}),
    ...(numberField && numberField.labels ? numberField.labels : {}),
  };
  const refId = frameRefId(frame);

  const rows = [];
  for (let index = 0; index < length; index += 1) {
    const row = {
      __refId: refId,
      ...frameLabels,
    };

    fields.forEach((field) => {
      row[field.name] = valueAt(field, index);
      if (field.labels) {
        Object.assign(row, field.labels);
      }
    });

    rows.push(row);
  }

  return rows;
};

const asString = (value) => {
  if (value === undefined || value === null) {
    return '';
  }

  return String(value);
};

const asNumber = (value) => {
  if (!hasValue(value)) {
    return null;
  }

  const number = Number(value);
  return Number.isFinite(number) ? number : null;
};

const hasValue = (value) => value !== undefined && value !== null && value !== '';

const valueForName = (row, name) => {
  if (hasValue(row[name])) {
    return row[name];
  }

  const expected = name.toLowerCase();
  const matchingKey = Object.keys(row).find((key) => {
    const normalized = key.toLowerCase();
    return hasValue(row[key])
      && (normalized === expected || normalized.startsWith(expected + ' '));
  });

  return matchingKey ? row[matchingKey] : undefined;
};

const firstValue = (row, names) => {
  for (const name of names) {
    const value = valueForName(row, name);
    if (hasValue(value)) {
      return value;
    }
  }

  return undefined;
};

const edgeIdFor = (row) => {
  const explicitEdgeId = asString(firstValue(row, ['edge_id', 'edge id', 'Edge ID']));
  if (explicitEdgeId) {
    return explicitEdgeId;
  }

  return [
    firstValue(row, ['source', 'node']),
    firstValue(row, ['target']),
    firstValue(row, ['transport']),
  ].map(asString).join('|');
};

const metricByRef = {
  A: 'latitude',
  B: 'longitude',
  C: 'latency_ms',
  D: 'loss_ppm',
  E: 'active',
  F: 'throughput_bps',
  G: 'conversational_best_effort_cost',
  H: 'target_latitude',
  I: 'target_longitude',
  J: 'latitude',
  K: 'longitude',
};

const metricFields = Object.values(metricByRef);
const metricFieldByName = Object.fromEntries(
  Object.entries(metricByRef).map(([refId, field]) => ['value #' + refId.toLowerCase(), field])
);
const metadataFields = [
  'source',
  'target',
  'transport',
  'city',
  'region',
  'country',
  'node_label',
  'target_city',
  'target_region',
  'target_country',
  'target_label',
];

const metricValueForRef = (row, refId) => {
  if (!refId) {
    return undefined;
  }

  const normalizedRefId = asString(refId).toUpperCase();
  const refSpecificValue = firstValue(row, [
    'Value #' + normalizedRefId,
    'value #' + normalizedRefId,
  ]);

  if (hasValue(refSpecificValue)) {
    return refSpecificValue;
  }

  return asString(row.__refId).toUpperCase() === normalizedRefId
    ? firstValue(row, ['Value', 'value'])
    : undefined;
};

const mergeRowsByEdge = (inputRows) => {
  const byEdge = new Map();

  inputRows.forEach((row) => {
    const edgeId = edgeIdFor(row);
    if (!edgeId || edgeId === '||') {
      return;
    }

    const merged = byEdge.get(edgeId) || { edge_id: edgeId };

    metadataFields.forEach((field) => {
      const value = firstValue(row, [field]);
      if (!hasValue(merged[field]) && hasValue(value)) {
        merged[field] = value;
      }
    });

    metricFields.forEach((field) => {
      const value = firstValue(row, [field]);
      const number = asNumber(value);
      if (number !== null) {
        merged[field] = number;
      }
    });

    Object.entries(row).forEach(([fieldName, value]) => {
      const metricField = metricFieldByName[fieldName.toLowerCase()];
      const number = asNumber(value);
      if (metricField && number !== null) {
        merged[metricField] = number;
      }
    });

    const refMetric = metricByRef[asString(row.__refId).toUpperCase()];
    if (refMetric) {
      const number = asNumber(metricValueForRef(row, row.__refId));
      if (number !== null) {
        merged[refMetric] = number;
      }
    }

    byEdge.set(edgeId, merged);
  });

  return Array.from(byEdge.values());
};

const rows = mergeRowsByEdge(data.series.flatMap(frameRows)).filter((row) => {
  const throughput = asNumber(firstValue(row, ['throughput_bps']));
  return Number.isFinite(throughput) && throughput > 0;
});

const labelFor = (id, explicitLabel) => {
  const label = asString(explicitLabel);
  if (label) {
    return label;
  }

  const nodeId = asString(id);
  return nodeId.split('.')[0] || nodeId || 'unknown';
};

const isCoordinate = (latitude, longitude) => {
  return Number.isFinite(latitude)
    && Number.isFinite(longitude)
    && latitude >= -90
    && latitude <= 90
    && longitude >= -180
    && longitude <= 180;
};

const nodesById = new Map();
const links = [];

const upsertNode = (id, label, city, region, country, latitude, longitude) => {
  const nodeId = asString(id);
  if (!nodeId || !isCoordinate(latitude, longitude)) {
    return null;
  }

  const existing = nodesById.get(nodeId) || {
    id: nodeId,
    label: labelFor(nodeId, label),
    city: asString(city),
    region: asString(region),
    country: asString(country),
    latitude,
    longitude,
    degree: 0,
  };

  existing.label = existing.label || labelFor(nodeId, label);
  existing.city = existing.city || asString(city);
  existing.region = existing.region || asString(region);
  existing.country = existing.country || asString(country);
  existing.latitude = Number.isFinite(existing.latitude) ? existing.latitude : latitude;
  existing.longitude = Number.isFinite(existing.longitude) ? existing.longitude : longitude;
  nodesById.set(nodeId, existing);
  return existing;
};

rows.forEach((row) => {
  const sourceLatitude = asNumber(firstValue(row, ['latitude', 'source_latitude']));
  const sourceLongitude = asNumber(firstValue(row, ['longitude', 'source_longitude']));
  const targetLatitude = asNumber(firstValue(row, ['target_latitude']));
  const targetLongitude = asNumber(firstValue(row, ['target_longitude']));

  const source = upsertNode(
    firstValue(row, ['source', 'node']),
    firstValue(row, ['node_label']),
    firstValue(row, ['city']),
    firstValue(row, ['region']),
    firstValue(row, ['country']),
    sourceLatitude,
    sourceLongitude
  );
  const target = upsertNode(
    firstValue(row, ['target']),
    firstValue(row, ['target_label']),
    firstValue(row, ['target_city']),
    firstValue(row, ['target_region']),
    firstValue(row, ['target_country']),
    targetLatitude,
    targetLongitude
  );

  if (!source || !target) {
    return;
  }

  source.degree += 1;
  target.degree += 1;
  links.push({
    id: edgeIdFor(row),
    source,
    target,
    transport: asString(firstValue(row, ['transport'])),
    latencyMs: asNumber(firstValue(row, ['latency_ms'])),
    lossPpm: asNumber(firstValue(row, ['loss_ppm'])),
    active: asNumber(firstValue(row, ['active'])) !== 0,
    throughputBps: asNumber(firstValue(row, ['throughput_bps'])),
    routeCost: asNumber(firstValue(row, ['conversational_best_effort_cost'])),
  });
});

const clamp = (value, min, max) => Math.max(min, Math.min(max, value));

const colorStops = [
  { value: 0, color: '#49E08A' },
  { value: 0.5, color: '#DCE85D' },
  { value: 0.75, color: '#F7B955' },
  { value: 1, color: '#FF5C5C' },
];

const hexToRgb = (hex) => {
  const value = hex.replace('#', '');
  return [
    parseInt(value.slice(0, 2), 16),
    parseInt(value.slice(2, 4), 16),
    parseInt(value.slice(4, 6), 16),
  ];
};

const rgbToHex = (rgb) => '#' + rgb.map((value) => clamp(Math.round(value), 0, 255).toString(16).padStart(2, '0')).join('');

const interpolateColor = (ratio) => {
  const clamped = clamp(ratio, 0, 1);
  const upperIndex = colorStops.findIndex((stop) => clamped <= stop.value);
  const upper = colorStops[Math.max(upperIndex, 1)];
  const lower = colorStops[Math.max(0, upperIndex - 1)];
  const span = upper.value - lower.value || 1;
  const localRatio = (clamped - lower.value) / span;
  const lowerRgb = hexToRgb(lower.color);
  const upperRgb = hexToRgb(upper.color);
  return rgbToHex(lowerRgb.map((channel, index) => channel + (upperRgb[index] - channel) * localRatio));
};

const linkMetric = (link) => {
  if (Number.isFinite(link.routeCost)) {
    return {
      label: 'route cost',
      value: link.routeCost,
      ratio: clamp(link.routeCost / 60, 0, 1),
    };
  }

  if (Number.isFinite(link.lossPpm) && link.lossPpm > 0) {
    return {
      label: 'loss',
      value: link.lossPpm,
      ratio: clamp(link.lossPpm / 100000, 0, 1),
    };
  }

  if (Number.isFinite(link.latencyMs)) {
    return {
      label: 'RTT',
      value: link.latencyMs,
      ratio: clamp(link.latencyMs / 250, 0, 1),
    };
  }

  return {
    label: 'active',
    value: link.active ? 0 : 1,
    ratio: link.active ? 0 : 1,
  };
};

const linkColor = (link) => link.active ? interpolateColor(linkMetric(link).ratio) : '#8A96A8';

const linkWidth = (link) => {
  const throughput = link.throughputBps || 0;
  if (throughput <= 0) {
    return 1.4;
  }

  return clamp(1.2 + (Math.log10(throughput) - 5) * 0.9, 1.4, 6);
};

const formatNumber = (value, decimals) => {
  if (!Number.isFinite(value)) {
    return 'n/a';
  }

  return value.toFixed(decimals);
};

const formatRate = (value) => {
  if (!Number.isFinite(value)) {
    return 'n/a';
  }

  const units = ['bps', 'Kbps', 'Mbps', 'Gbps', 'Tbps'];
  let scaled = value;
  let unitIndex = 0;

  while (scaled >= 1000 && unitIndex < units.length - 1) {
    scaled /= 1000;
    unitIndex += 1;
  }

  return scaled.toFixed(scaled >= 10 || unitIndex === 0 ? 0 : 1) + ' ' + units[unitIndex];
};

const escapeHtml = (value) => asString(value).replace(/[&<>"']/g, (character) => ({
  '&': '&amp;',
  '<': '&lt;',
  '>': '&gt;',
  '"': '&quot;',
  "'": '&#39;',
}[character]));

const place = (node) => [node.city, node.region, node.country].filter(Boolean).join(', ');
const nodes = Array.from(nodesById.values()).sort((left, right) => left.label.localeCompare(right.label));

const nodeData = nodes.map((node) => ({
  name: node.label,
  label: node.label,
  node,
  value: [node.longitude, node.latitude, 0],
  symbolSize: clamp(3.5 + Math.sqrt(Math.max(1, node.degree)) * 1.15, 4, 9),
  itemStyle: {
    color: '#FFFFFF',
    borderColor: '#59DCE8',
    borderWidth: 1,
  },
}));

const edgeData = links.map((link) => {
  const metric = linkMetric(link);
  return {
    name: link.source.label + ' -> ' + link.target.label,
    link,
    metric,
    value: metric.value,
    coords: [
      [link.source.longitude, link.source.latitude],
      [link.target.longitude, link.target.latitude],
    ],
    lineStyle: {
      color: linkColor(link),
      opacity: link.active ? 0.96 : 0.32,
      width: linkWidth(link),
    },
  };
});

const createGlobeTexture = () => {
  if (typeof document === 'undefined') {
    return undefined;
  }

  const canvas = document.createElement('canvas');
  canvas.width = 2048;
  canvas.height = 1024;
  const ctx = canvas.getContext('2d');
  if (!ctx) {
    return undefined;
  }

  const ocean = ctx.createLinearGradient(0, 0, 0, canvas.height);
  ocean.addColorStop(0, isDark ? '#0A223A' : '#BBDFFF');
  ocean.addColorStop(0.5, isDark ? '#12486F' : '#69B5E6');
  ocean.addColorStop(1, isDark ? '#061427' : '#D7EEFF');
  ctx.fillStyle = ocean;
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  const project = (coordinate) => {
    const longitude = Number(coordinate[0]);
    const latitude = Number(coordinate[1]);
    return [
      ((longitude + 180) / 360) * canvas.width,
      ((90 - latitude) / 180) * canvas.height,
    ];
  };

  ctx.strokeStyle = isDark ? 'rgba(180, 230, 255, 0.20)' : 'rgba(22, 76, 118, 0.22)';
  ctx.lineWidth = 1;
  for (let longitude = -180; longitude <= 180; longitude += 30) {
    const x = ((longitude + 180) / 360) * canvas.width;
    ctx.beginPath();
    ctx.moveTo(x, 0);
    ctx.lineTo(x, canvas.height);
    ctx.stroke();
  }
  for (let latitude = -60; latitude <= 60; latitude += 30) {
    const y = ((90 - latitude) / 180) * canvas.height;
    ctx.beginPath();
    ctx.moveTo(0, y);
    ctx.lineTo(canvas.width, y);
    ctx.stroke();
  }

  const fallbackContinents = [
    [[-168, 72], [-52, 72], [-48, 50], [-80, 25], [-98, 15], [-125, 22], [-150, 50], [-168, 72]],
    [[-82, 12], [-36, 10], [-46, -55], [-72, -55], [-82, 12]],
    [[-18, 72], [172, 72], [162, 6], [104, -8], [75, 5], [44, -35], [14, -35], [-18, 30], [-18, 72]],
    [[112, -11], [154, -12], [154, -44], [112, -44], [112, -11]],
    [[-52, 74], [-16, 74], [-18, 58], [-48, 58], [-52, 74]],
  ];

  const drawRing = (ring) => {
    ring.forEach((coordinate, index) => {
      const [x, y] = project(coordinate);
      if (index === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }
    });
    ctx.closePath();
  };

  const drawPolygon = (polygon) => {
    ctx.beginPath();
    polygon.forEach(drawRing);
    ctx.fill('evenodd');
    ctx.stroke();
  };

  const drawGeometry = (geometry) => {
    if (!geometry) {
      return;
    }
    if (geometry.type === 'Polygon') {
      drawPolygon(geometry.coordinates);
    }
    if (geometry.type === 'MultiPolygon') {
      geometry.coordinates.forEach(drawPolygon);
    }
  };

  ctx.fillStyle = isDark ? '#2F6B54' : '#78B97B';
  ctx.strokeStyle = isDark ? 'rgba(230, 246, 233, 0.70)' : 'rgba(25, 78, 45, 0.62)';
  ctx.lineWidth = 0.85;

  const echarts = context.echarts;
  const map = echarts && echarts.getMap && (echarts.getMap('world') || echarts.getMap('World'));
  const geoJson = map && (map.geoJson || map.geoJSON);
  const features = geoJson && Array.isArray(geoJson.features) ? geoJson.features : null;

  if (features && features.length > 0) {
    features.forEach((feature) => drawGeometry(feature.geometry));
  } else {
    fallbackContinents.forEach((ring) => drawPolygon([ring]));
  }

  return canvas;
};

const textColor = isDark ? '#D7E7F7' : '#18334D';
const globe = {
  baseTexture: createGlobeTexture(),
  shading: 'lambert',
  globeRadius: 72,
  environment: isDark ? '#030711' : '#E9F5FF',
  light: {
    ambient: {
      intensity: 0.72,
    },
    main: {
      intensity: 1.05,
      shadow: false,
    },
  },
  viewControl: {
    autoRotate: true,
    autoRotateSpeed: 1.2,
    distance: 165,
    minDistance: 20,
    maxDistance: 260,
    targetCoord: links.length > 0
      ? [links[0].source.longitude, links[0].source.latitude]
      : nodes.length > 0
        ? [nodes[0].longitude, nodes[0].latitude]
        : [0, 20],
  },
};

return {
  backgroundColor: 'transparent',
  tooltip: {
    trigger: 'item',
    confine: true,
    formatter: (params) => {
      if (params.seriesName === 'Links') {
        const link = params.data.link;
        return [
          '<strong>' + escapeHtml(link.source.label) + ' -> ' + escapeHtml(link.target.label) + '</strong>',
          'Transport: ' + escapeHtml(link.transport || 'n/a'),
          'Status: ' + (link.active ? 'active' : 'inactive'),
          'RTT: ' + formatNumber(link.latencyMs, 1) + ' ms',
          'Loss: ' + formatNumber((link.lossPpm || 0) / 10000, 3) + '%',
          'Throughput: ' + formatRate(link.throughputBps),
          'Route cost: ' + formatNumber(link.routeCost, 2),
          'Color metric: ' + escapeHtml(linkMetric(link).label),
        ].join('<br />');
      }

      const node = params.data.node;
      return [
        '<strong>' + escapeHtml(node.label) + '</strong>',
        'Node: ' + escapeHtml(node.id),
        place(node) ? 'Location: ' + escapeHtml(place(node)) : '',
        'Links: ' + node.degree,
        'Lat/Lon: ' + formatNumber(node.latitude, 4) + ', ' + formatNumber(node.longitude, 4),
      ].filter(Boolean).join('<br />');
    },
  },
  legend: {
    show: false,
    selectedMode: false,
  },
  title: links.length === 0 && nodes.length === 0 ? {
    text: 'No active S2S links with traffic and usable source and target coordinates',
    left: 'center',
    top: 'middle',
    textStyle: {
      color: textColor,
      fontSize: 14,
      fontWeight: 'normal',
    },
  } : undefined,
  globe,
  series: [
    {
      name: 'Links',
      type: 'lines3D',
      coordinateSystem: 'globe',
      blendMode: 'lighter',
      lineStyle: {
        width: 2.2,
        opacity: 0.92,
      },
      effect: {
        show: true,
        period: 4,
        trailWidth: 2.2,
        trailLength: 0.18,
        trailOpacity: 0.55,
        trailColor: '#C7F8FF',
      },
      data: edgeData,
    },
    {
      name: 'Nodes',
      type: 'scatter3D',
      coordinateSystem: 'globe',
      symbol: 'circle',
      symbolSize: (value, params) => params.data.symbolSize,
      itemStyle: {
        color: '#FFFFFF',
        borderColor: '#59DCE8',
        borderWidth: 1,
      },
      label: {
        show: true,
        distance: 3,
        formatter: (params) => params.data.label,
        textStyle: {
          color: textColor,
          fontSize: 11,
          backgroundColor: isDark ? 'rgba(3, 7, 17, 0.35)' : 'rgba(255, 255, 255, 0.38)',
          borderRadius: 3,
          padding: [2, 4],
        },
      },
      emphasis: {
        itemStyle: {
          color: '#D6FBFF',
        },
        label: {
          show: true,
        },
      },
      data: nodeData,
    },
  ],
};

